from lib import *
S = SS('g13')
steps = [
    step("同样 5 个字段(bool、int64、bool、int32、bool),Bad 的顺序是 a bool、b int64、c bool、d int32、e bool:偏移 0、8、16、20、24,b 前填充 7 字节、d 前填充 3 字节、末尾填充 7 字节,Sizeof = 32、Alignof = 8;Good 的顺序是 int64、int32、bool、bool、bool:偏移 0、8、12、13、14,只有末尾填充 1 字节,Sizeof = 16。", t=tl(S(1)), done=lidx(S(1), 'Good:Sizeof = 16', 'offset 12', 'offset 13', 'offset 14'), mark=lidx(S(1), 'Bad:Sizeof = 32', '前面填充 7 字节', '前面填充 3 字节', '末尾填充 7 字节'), b=bars([['Bad(字节)', 32, '32'], ['Good(字节)', 16, '16']], 32, mark=[0], done=[1]), kv=KV([['Bad', '32 字节:填充 7 + 3 + 7 = 17 字节'], ['Good', '16 字节:末尾填充 1 字节'], ['规则', '字段按自己的对齐放;结构体大小补齐到最大对齐']], ['Bad'])),
    step("常见类型的大小与对齐(arm64):bool 1/1、int16 2/2、int32 4/4、int64 8/8、float32 4/4、complex128 16/8、string 16/8、[]int 24/8、any 16/8、map[int]int 8/8、[3]byte 3/1、struct{} 0/1(Sizeof/Alignof)。对齐就是该类型里最大成员的对齐;string、切片、接口、map 都是 8 字节对齐。", t=tl(S(2)), done=lidx(S(2), 'int64', 'string', '[]int', 'any'), mark=lidx(S(2), 'complex128', '[3]byte', 'struct{}'), kv=KV([['bool / int16 / int32 / int64', '大小 1 / 2 / 4 / 8,对齐 = 大小'], ['complex128', '16 字节,对齐 8'], ['string / any', '16 字节,对齐 8'], ['[]int', '24 字节,对齐 8'], ['[3]byte / struct{}', '3 字节对齐 1 / 0 字节对齐 1']], ['complex128'])),
    step("零大小字段放末尾会多占空间:ZeroTail{a int64; z struct{}} 的 Sizeof = 16(z 的偏移是 8,末尾填充 8 字节);ZeroHead{z struct{}; a int64} 的 Sizeof = 8(z 与 a 的偏移都是 0)。", t=tl(S(3)), done=lidx(S(3), 'ZeroHead'), mark=lidx(S(3), 'ZeroTail', '末尾填充 8 字节'), b=bars([['ZeroTail(字节)', 16, '16'], ['ZeroHead(字节)', 8, '8']], 16, mark=[0], done=[1]), kv=KV([['ZeroTail{a int64; z struct{}}', '16 字节'], ['ZeroHead{z struct{}; a int64}', '8 字节']], ['ZeroTail{a int64; z struct{}}'])),
    step("100 万个元素的切片:[]Bad 是 32 × 1000000 = 30.5 MiB,[]Good 是 16 × 1000000 = 15.3 MiB,省 50.0%。遍历求和 d 字段(7 轮取中位数):[]Bad 603978.48 ns/op,[]Good 610044.56 ns/op——在这个顺序读的循环里耗时没有差别,收益只在内存。", t=tl(S(4)), done=lidx(S(4), '[]Bad  32'), mark=lidx(S(4), '遍历 []Bad', '遍历 []Good'), b=bars([['[]Bad 内存(MiB)', 30.5, '30.5'], ['[]Good 内存(MiB)', 15.3, '15.3'], ['遍历 []Bad(µs)', 604, '604'], ['遍历 []Good(µs)', 610, '610']], 610, done=[1], mark=[0, 2, 3]), kv=KV([['内存', '30.5 MiB → 15.3 MiB(省 50.0%)'], ['顺序遍历求和 d', '603978 ns vs 610045 ns,没有可测的差别']], ['内存'])),
    step("同一个结构体在不同 GOARCH 上不同(用 go/types 的 gc 规则计算):amd64 与 arm64 上 Bad = 32、Good = 16;386 与 arm 上 Bad = 24(Alignof 4,偏移 0 4 12 16 20)、Good = 16(偏移 0 8 12 13 14)。32 位平台上 int64 只按 4 字节对齐,所以填充更少。", t=tl(S(5)), done=lidx(S(5), 'GOARCH=amd64', 'GOARCH=arm64'), mark=lidx(S(5), 'GOARCH=386   Bad', 'GOARCH=arm   Bad'), kv=KV([['amd64 / arm64', 'Bad 32、Good 16'], ['386 / arm', 'Bad 24(对齐 4)、Good 16'], ['原因', '32 位上 int64 按 4 字节对齐']], ['386 / arm'])),
    step("fieldalignment(golang.org/x/tools v0.51.0)作为 vettool 运行:Bad has size 32 but the optimal size is 16 leading to a waste of 16 bytes (50%);Good 没有报告;Mixed{bool, string, int32, *int, bool, int64} has size 56 (allocator size class 64) but the optimal size is 40 (allocator size class 48) leading to a waste of 16 bytes (25%)——它还把分配器的 size class 算进去了。", t=tl(S(6)), done=lidx(S(6), 'Bad has size 32'), mark=lidx(S(6), 'Mixed has size 56'), b=bars([['Mixed 当前(字节)', 56, '56'], ['Mixed 最优(字节)', 40, '40'], ['Mixed 当前 size class', 64, '64'], ['Mixed 最优 size class', 48, '48']], 64, mark=[0, 2], done=[1, 3]), kv=KV([['Bad', '32 → 16,浪费 16 字节(50%)'], ['Good', '无报告'], ['Mixed', '56(size class 64)→ 40(size class 48),浪费 16 字节(25%)']], ['Mixed'])),
]
A = mkartg('g13', 13, 'Go,结构体,内存对齐,填充,fieldalignment,真实验证,动画演示',
    '用 Go 1.27.1 实测结构体内存布局:同样 5 个字段,bool/int64/bool/int32/bool 的顺序占 32 字节(填充 17 字节),重排成 int64、int32、bool×3 只占 16 字节;零大小字段放末尾多占 8 字节;100 万个元素的切片省 50% 内存但顺序遍历耗时没有差别;386/arm 上同一个结构体更小(int64 只对齐到 4);fieldalignment 能找出可优化的结构体并把分配器 size class 算进去。',
    '结构体里字段的顺序会影响大小:每个字段要放在自己对齐的地址上,整个结构体的大小还要补齐到最大对齐。这篇用 reflect 打印每个字段的偏移与填充,对比两种字段顺序,量出差别,再用 fieldalignment 工具自动发现这类问题。',
    [('32 → 16', '同样 5 个字段,按 bool、int64、bool、int32、bool 排列占 32 字节,重排后占 16 字节'), ('50.0%', '100 万个元素的切片省下的内存'), ('0 差别', '顺序读 d 字段求和的耗时(603978 ns vs 610045 ns)')],
    [('偏移与填充', '<p>规则是两条:每个字段的偏移必须是它对齐值的整数倍;结构体的大小必须是它最大对齐值的整数倍。Bad 里 <code>int64</code> 前面的 7 字节、<code>int32</code> 前面的 3 字节、末尾 7 字节都是填充,合计 17 字节。把大对齐的字段放前面,小字段挤在一起,填充几乎消失。</p>'),
     ('常见类型的对齐', '<p>对齐值就是类型里最大成员的对齐:<code>string</code>、切片、接口、<code>map</code> 都是 8 字节对齐(它们内部是指针与整数);<code>complex128</code> 是 16 字节但只要 8 字节对齐;数组的对齐等于元素的对齐;<code>struct{}</code> 大小是 0、对齐是 1。</p>'),
     ('末尾的零大小字段', '<p>空结构体字段放在结构体的最后会让整个结构体多出一个对齐单位(上面 8 → 16 字节),放在前面则没有代价。我没有读编译器里这条规则的源码(合理的解释是避免指向结构体末尾之后的指针,但这只是我的推测,没有验证)。</p>'),
     ('省内存,不一定更快', '<p>切片元素大小减半,100 万个元素省了 15 MiB。但“只读一个字段、顺序遍历”的循环里耗时没有区别,所以这个例子里收益只是内存与 GC 扫描量;缓存压力更大的访问模式(随机访问、遍历很多字段)可能看到差别,本文没有测。</p>'),
     ('不同平台不同结果', '<p>386 与 arm 上 <code>int64</code> 只要 4 字节对齐,所以同一个结构体的大小与偏移不同。我用标准库 <code>go/types</code> 按 gc 编译器的规则计算,没有真的运行 32 位程序。要在 32 位平台上对 64 位字段做原子操作,还有额外的对齐要求(<code>sync/atomic</code> 文档里写明),本文没有验证。</p>'),
     ('用工具发现', '<p><code>fieldalignment</code> 是 <code>golang.org/x/tools</code> 里的分析器,不在 <code>go vet</code> 默认的检查里,需要单独安装并作为 <code>-vettool</code> 运行。它不只比较字节数,还会提示分配器的 size class(56 字节的结构体分配时占 64 字节)。注意工具建议的字段顺序有时会让结构体更难读,是否值得要看这个类型有多少实例。</p>')],
    steps,
    [ENV_G + '。reflect 的偏移来自 reflect.StructField.Offset;不同 GOARCH 的数字来自 go/types 的 SizesFor("gc", arch),没有运行 386 或 arm 程序;fieldalignment 是 golang.org/x/tools v0.51.0 (经代理 go install),作为 go vet -vettool 运行;遍历基准测试 7 轮取中位数',
     '没有验证:386 / arm 上的真实内存布局、sync/atomic 对 64 位字段的对齐要求、随机访问或多字段访问下的缓存影响、编译器对末尾零大小字段规则的实现与原因、带 cgo 的结构体布局',],
    '结构体的对齐与填充')
